import media from './flowPilotMedia.json';
import { CAMPUS_JOURNEY, MEMORY_STOPS } from './journey';
import { smoothstep } from '@/lib/sceneProgress';

// Content-addressed assets are generated by scripts/prepare-flow-pilot.py.
export const FLOW_PILOT = media;

export function getFlowArrivalTime(progress: number, motionEnabled: boolean) {
  const arrived = MEMORY_STOPS[0].start;
  const amount = motionEnabled
    ? smoothstep(CAMPUS_JOURNEY.start, arrived, progress)
    : progress >= arrived ? 1 : 0;
  return amount * FLOW_PILOT.transition.lastFrameTime;
}
